using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SchoolERP.Domain.Entities;namespace SchoolERP.Infrastructure.Persistence.Configurations;public sealed class SchoolCalendarEventConfiguration:IEntityTypeConfiguration<SchoolCalendarEvent>{public void Configure(EntityTypeBuilder<SchoolCalendarEvent>b){b.ToTable("school_calendar_events",t=>{t.HasCheckConstraint("ck_calendar_dates","end_date >= start_date");t.HasCheckConstraint("ck_calendar_status","status BETWEEN 1 AND 4");});b.ConfigureAudit();b.Property(x=>x.TenantId).HasColumnName("tenant_id");b.Property(x=>x.SchoolId).HasColumnName("school_id");b.Property(x=>x.CampusId).HasColumnName("campus_id");b.Property(x=>x.AcademicYearId).HasColumnName("academic_year_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(200).IsRequired();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);b.Property(x=>x.Type).HasColumnName("type").HasConversion<int>();b.Property(x=>x.StartDate).HasColumnName("start_date");b.Property(x=>x.EndDate).HasColumnName("end_date");b.Property(x=>x.IsAllDay).HasColumnName("is_all_day");b.Property(x=>x.StartTime).HasColumnName("start_time");b.Property(x=>x.EndTime).HasColumnName("end_time");b.Property(x=>x.IsWorkingDayOverride).HasColumnName("is_working_day_override");b.Property(x=>x.ColorHex).HasColumnName("color_hex").HasMaxLength(7);b.Property(x=>x.Location).HasColumnName("location").HasMaxLength(200);b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(1000);b.Property(x=>x.Recurrence).HasColumnName("recurrence").HasConversion<int>();b.Property(x=>x.RecurrenceEndDate).HasColumnName("recurrence_end_date");b.Property(x=>x.Status).HasColumnName("status").HasConversion<int>();b.Property(x=>x.PublishedAt).HasColumnName("published_at");b.Property(x=>x.CancelledAt).HasColumnName("cancelled_at");b.Property(x=>x.ArchivedAt).HasColumnName("archived_at");b.HasOne(x=>x.Tenant).WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.School).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Campus).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.CampusId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.AcademicYear).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TenantId);b.HasIndex(x=>x.SchoolId);b.HasIndex(x=>x.CampusId);b.HasIndex(x=>x.AcademicYearId);b.HasIndex(x=>new{x.SchoolId,x.Code}).IsUnique().HasFilter("code IS NOT NULL").HasDatabaseName("ux_calendar_school_code");b.HasIndex(x=>new{x.SchoolId,x.StartDate,x.EndDate});b.HasIndex(x=>new{x.SchoolId,x.Status});b.HasIndex(x=>new{x.SchoolId,x.Type});}}
